create extension if not exists pgcrypto;
create type project_status as enum ('fikir','gelistiriliyor','test','aktif','bakim','beklemede','tamamlandi','arsiv');
create type health_status as enum ('healthy','warning','critical','unknown');
create table customers(id uuid primary key default gen_random_uuid(),name text not null,contact_person text,phone text,email text,website text,address text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table projects(id uuid primary key default gen_random_uuid(),name text not null,short_name text,description text,customer_id uuid references customers on delete set null,status project_status not null default 'fikir',start_date date,delivery_date date,go_live_date date,live_url text,favorite boolean not null default false,critical boolean not null default false,archived boolean not null default false,archived_at timestamptz,health_status health_status not null default 'unknown',last_checked_at timestamptz,last_backup_at timestamptz,github_repo text,github_repo_name text,github_private boolean,github_default_branch text,github_last_commit_hash text,github_last_commit_date timestamptz,vercel_project_name text,vercel_dashboard_url text,vercel_production_url text,vercel_preview_url text,vercel_deploy_status text,vercel_last_deploy_date timestamptz,supabase_project_name text,supabase_project_ref text,supabase_region text,supabase_dashboard_url text,supabase_database_type text,supabase_has_storage boolean default false,supabase_has_edge_functions boolean default false,supabase_has_auth boolean default false,node_version text,package_manager text,install_command text,development_command text,build_command text,start_command text,environment_variables jsonb not null default '{}'::jsonb,recovery_notes text,created_by uuid references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table technologies(id uuid primary key default gen_random_uuid(),name text unique not null);
create table project_technologies(project_id uuid references projects on delete cascade,technology_id uuid references technologies on delete cascade,primary key(project_id,technology_id));
create table tags(id uuid primary key default gen_random_uuid(),name text unique not null,color text);
create table project_tags(project_id uuid references projects on delete cascade,tag_id uuid references tags on delete cascade,primary key(project_id,tag_id));
create table source_backups(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects on delete cascade,filename text not null,storage_path text unique not null,version text,description text,file_size bigint,uploaded_by uuid references auth.users,commit_hash text,branch text,git_tag text,notes text,is_latest boolean default false,verified boolean default false,verified_at timestamptz,file_hash text not null,backup_type text not null default 'manual' check(backup_type in('manual','release','pre_deploy','automatic')),created_at timestamptz not null default now());
create table database_backups(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects on delete cascade,filename text not null,storage_path text unique not null,version text,description text,file_size bigint,uploaded_by uuid references auth.users,file_hash text not null,created_at timestamptz not null default now());
create table project_files(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects on delete cascade,filename text not null,storage_path text unique not null,category text not null,file_size bigint,file_hash text not null,uploaded_by uuid references auth.users,created_at timestamptz not null default now());
create table domains(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects on delete cascade,domain text unique not null,registrar text,purchase_date date,expiry_date date,auto_renew boolean default false,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table project_notes(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects on delete cascade,title text not null,content text not null,category text not null,pinned boolean default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table releases(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects on delete cascade,version text not null,release_date date,changelog text,source_backup_id uuid references source_backups on delete set null,database_backup_id uuid references database_backups on delete set null,notes text,created_at timestamptz not null default now());
create table activity_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,project_id uuid references projects on delete set null,action text not null,metadata jsonb default '{}',created_at timestamptz not null default now());
create or replace function update_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end;$$;
do $$ declare t text; begin foreach t in array array['customers','projects','domains','project_notes'] loop execute format('create trigger set_updated_at before update on %I for each row execute function update_updated_at()',t);end loop;end $$;
create index projects_status_idx on projects(status);create index projects_archived_idx on projects(archived);create index projects_favorite_idx on projects(favorite);create index projects_critical_idx on projects(critical);create index projects_created_at_idx on projects(created_at desc);create index source_backups_project_idx on source_backups(project_id,created_at desc);create index source_backups_latest_idx on source_backups(project_id,is_latest);create index database_backups_project_idx on database_backups(project_id,created_at desc);create index project_files_project_idx on project_files(project_id);create index domains_project_idx on domains(project_id);create index domains_expiry_idx on domains(expiry_date);create index project_notes_project_idx on project_notes(project_id,pinned desc);
alter table customers enable row level security;alter table projects enable row level security;alter table technologies enable row level security;alter table project_technologies enable row level security;alter table tags enable row level security;alter table project_tags enable row level security;alter table source_backups enable row level security;alter table database_backups enable row level security;alter table project_files enable row level security;alter table domains enable row level security;alter table project_notes enable row level security;alter table releases enable row level security;alter table activity_logs enable row level security;
do $$ declare t text; begin foreach t in array array['customers','projects','technologies','project_technologies','tags','project_tags','source_backups','database_backups','project_files','domains','project_notes','releases','activity_logs'] loop execute format('create policy "authenticated full access" on %I for all to authenticated using (true) with check (true)',t);end loop;end $$;
insert into storage.buckets(id,name,public,file_size_limit) values('project-files','project-files',false,104857600) on conflict(id) do update set public=false,file_size_limit=104857600;
create policy "authenticated storage read" on storage.objects for select to authenticated using(bucket_id='project-files');create policy "authenticated storage insert" on storage.objects for insert to authenticated with check(bucket_id='project-files');create policy "authenticated storage delete" on storage.objects for delete to authenticated using(bucket_id='project-files');
insert into technologies(name) values('Next.js'),('React'),('Supabase'),('Flutter'),('PostgreSQL'),('TypeScript'),('Tailwind CSS'),('Node.js') on conflict do nothing;
